const DICT = { uz, ru, en };
export const LANGS = ['uz', 'ru', 'en'];
let lang = 'uz';
try { const s = localStorage.getItem('aes-lang'); if (LANGS.includes(s)) lang = s; } catch {}

export const getLang = () => lang;
export function setLang(l) {
  if (!LANGS.includes(l)) return;
  lang = l;
  try { localStorage.setItem('aes-lang', l); } catch {}
  document.documentElement.lang = l;
  applyStatic();
  window.dispatchEvent(new CustomEvent('langchange', { detail: l }));
}
export function t(key, vars) {
  let s = DICT[lang][key] ?? uz[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return s;
}
export function applyStatic() {
  document.title = t('meta.title');
  document.querySelector('meta[name=description]')?.setAttribute('content', t('meta.desc'));
  document.querySelectorAll('[data-i18n]').forEach((el) => { el.innerHTML = t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  document.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); });
  document.querySelectorAll('.langsw button').forEach((b) => b.classList.toggle('on', b.dataset.l === lang));
}
